<?php declare(strict_types=1); ?>
<section class="view hidden" id="view-student-dashboard" data-title="Dashboard" data-section="Student workspace"><div class="page-heading"><div><span class="eyebrow">YOUR CLUBCONNECT</span><h1>Welcome back, <?= e($currentUser['first_name'] ?? 'student') ?></h1><p class="muted">Here is what is happening around your campus.</p></div><button class="button button-primary" data-view="events">Explore events <span>→</span></button></div><div class="dashboard-grid"><article class="panel schedule-panel"><div class="panel-heading"><div><h2>Your registered events</h2><p class="muted">Do not miss your next experience.</p></div><button class="text-button" data-view="registrations">View all →</button></div><?php if ($userRegistrations === []): ?><div class="empty-state"><p class="muted">You have no active event registrations.</p></div><?php else: ?><div class="event-list"><?php foreach (array_slice($userRegistrations, 0, 3) as $registration): ?><a class="event-row" data-view="event-details" data-route="true" href="index.php?view=event-details&amp;id=<?= (int) $registration['event_id'] ?>"><span class="date-tile"><strong><?= e(date('d', strtotime((string) $registration['event_date']))) ?></strong><span><?= e(strtoupper(date('M', strtotime((string) $registration['event_date'])))) ?></span></span><span class="event-info"><strong><?= e($registration['title']) ?></strong><span><?= e(date('g:i A', strtotime((string) $registration['event_time']))) ?> · <?= e($registration['venue']) ?></span></span><span class="tag tag-blue"><?= e(ucfirst((string) $registration['status'])) ?></span></a><?php endforeach; ?></div><?php endif; ?></article><article class="panel club-panel"><div class="panel-heading"><div><h2>Your clubs</h2><p class="muted">Communities you are part of.</p></div><button class="text-button" data-view="clubs">Explore →</button></div><?php if ($userClubs === []): ?><div class="empty-state"><p class="muted">You have not joined any clubs yet.</p></div><?php else: foreach ($userClubs as $club): $tone = club_tone((string) $club['category']); ?><a class="club-mini" data-view="club-details" data-route="true" href="index.php?view=club-details&amp;id=<?= (int) $club['club_id'] ?>"><span class="club-avatar <?= e($tone) ?>">✦</span><div><strong><?= e($club['name']) ?></strong><span><?= e($club['category']) ?></span></div><span class="online-dot"></span></a><?php endforeach; endif; ?></article></div></section>
